solution.Range.java:
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;

public class Range implements Iterable<Integer> {
    private final int start, end, step;

    private Range(int start, int end, int step) {
        if (step == 0) throw new IllegalArgumentException("step cannot be 0");
        this.start = start;
        this.end = end;
        this.step = step;
    }

    public static Range of(int start, int end) { return new Range(start, end, 1); }
    public static Range of(int start, int end, int step) { return new Range(start, end, step); }

    public int size() {
        if (step > 0) return start >= end ? 0 : (end - start + step - 1) / step;
        return start <= end ? 0 : (start - end - step - 1) / -step;
    }

    public List<Integer> toList() {
        List<Integer> out = new ArrayList<>();
        for (int n : this) out.add(n);
        return out;
    }

    @Override
    public Iterator<Integer> iterator() {
        return new Walker();
    }

    private class Walker implements Iterator<Integer> {
        private int next = start;

        public boolean hasNext() {
            return step > 0 ? next < end : next > end;
        }

        public Integer next() {
            if (!hasNext()) throw new NoSuchElementException();
            int value = next;
            next += step;
            return value;
        }
    }
}

unitTests:
test("ranges", () -> {
    checkEq(Range.of(0, 5).toList(), java.util.List.of(0, 1, 2, 3, 4));
    checkEq(Range.of(1, 10, 4).toList(), java.util.List.of(1, 5, 9));
    checkEq(Range.of(10, 0, -3).toList(), java.util.List.of(10, 7, 4, 1));
    checkEq(Range.of(3, 3).toList(), java.util.List.of());
    checkEq(Range.of(5, 1).toList(), java.util.List.of());
});

test("sizes", () -> {
    checkEq(Range.of(0, 5).size(), 5);
    checkEq(Range.of(1, 10, 4).size(), 3);
    checkEq(Range.of(10, 0, -3).size(), 4);
    checkEq(Range.of(5, 1).size(), 0);
});

test("iterator rules", () -> {
    checkThrows(IllegalArgumentException.class, () -> Range.of(0, 5, 0));
    var it = Range.of(0, 1).iterator();
    checkEq(it.next(), 0);
    check(!it.hasNext(), "the range should be finished");
    checkThrows(java.util.NoSuchElementException.class, it::next);
    int total = 0;
    for (int n : Range.of(1, 101)) total += n;
    checkEq(total, 5050);
});

